import type { Database as SQLiteDatabase } from 'better-sqlite3';
import initMigration from '../drizzle/0000_init.sql?raw';
import buttonAppearanceMigration from '../drizzle/0001_button_appearance.sql?raw';
import customIconsMigration from '../drizzle/0002_custom_icons.sql?raw';

/**
 * Ordered list of SQL migrations. The SQL files are generated by Drizzle Kit
 * (`pnpm db:generate`) and bundled as raw strings so they also work from a
 * packaged Electron app where no migration folder is shipped on disk.
 */
export const migrations: ReadonlyArray<{ id: string; sql: string }> = [
  { id: '0000_init', sql: initMigration },
  { id: '0001_button_appearance', sql: buttonAppearanceMigration },
  { id: '0002_custom_icons', sql: customIconsMigration },
];

const MIGRATIONS_TABLE = '__condeck_migrations';

function ensureMigrationsTable(sqlite: SQLiteDatabase): void {
  sqlite
    .prepare(
      `CREATE TABLE IF NOT EXISTS ${MIGRATIONS_TABLE} (
        id TEXT PRIMARY KEY NOT NULL,
        applied_at TEXT NOT NULL
      )`,
    )
    .run();
}

function appliedMigrationIds(sqlite: SQLiteDatabase): Set<string> {
  const rows = sqlite.prepare(`SELECT id FROM ${MIGRATIONS_TABLE}`).all() as Array<{ id: string }>;
  return new Set(rows.map((row) => row.id));
}

function splitStatements(sql: string): string[] {
  return sql
    .split('--> statement-breakpoint')
    .map((statement) => statement.trim())
    .filter((statement) => statement.length > 0);
}

/**
 * Applies all pending migrations inside a transaction per migration, then
 * records them. Safe to call on every application start (DATABASE_DESIGN.md §9).
 */
export function runMigrations(sqlite: SQLiteDatabase): string[] {
  ensureMigrationsTable(sqlite);
  const applied = appliedMigrationIds(sqlite);
  const newlyApplied: string[] = [];

  for (const migration of migrations) {
    if (applied.has(migration.id)) {
      continue;
    }

    const apply = sqlite.transaction(() => {
      for (const statement of splitStatements(migration.sql)) {
        sqlite.exec(statement);
      }
      sqlite
        .prepare(`INSERT INTO ${MIGRATIONS_TABLE} (id, applied_at) VALUES (?, ?)`)
        .run(migration.id, new Date().toISOString());
    });

    apply();
    newlyApplied.push(migration.id);
  }

  return newlyApplied;
}
